-- Rifts World Book 36: Sovietski: the 11 kinds of tank round, printed 190-192.
-- 11 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~389-sovietski-v4-rounds.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('sovietski-tank-round-armor-piercing', 'Tank Round: Armor Piercing (AP)', 'rifts', 'weapon', NULL, 900, 'Per round: 900 credits (85mm), 1,600 (100mm), 2,200 (120mm), 3,000 (200mm).', '85mm 1D4x10 M.D.; 100mm 1D6x10 M.D.; 120mm 2D4x10 M.D.; 200mm 2D6x10 M.D. No blast radius.', 1, 'As per the tank gun firing it', NULL, NULL, NULL, NULL, NULL, 'A Sovietski tank shell, usually a rod-shaped solid penetrator with a hardened tip, made to bore through M.D.C. armor, vehicles, giant robots and thin walls and to hurt Mega-Damage creatures. Against a vehicle only 30% of the damage lands on the Main Body and 50% on the Reinforced Crew Compartment (also called the pilot, internal or concealed crew compartment); the rest is lost. Once that compartment is gone, or where a vehicle has none, the round goes through: 30% to the Main Body, and when it strikes the front, a side or the top, a 01-70% roll means that a crewman or passenger takes half its damage. On 71-00 nobody is hit, and the G.M. decides whether radios, radar, cameras, heating, cargo or personal belongings suffered. A manned turret works the same way, and many turrets have no reinforced compartment, which is why Sovietski tankers wear Red Star armor inside or are Light Machines in light or medium cyborg armor. Anti-armor.', 'Rifts World Book 36: Sovietski p.190', NULL),
  ('sovietski-tank-round-high-explosive', 'Tank Round: High Explosive (HE)', 'rifts', 'weapon', NULL, 600, 'Per round: 600 credits (85mm), 900 (100mm), 1,200 (120mm), 1,600 (200mm).', '85mm 5D6 M.D., 100mm 6D6 M.D., 120mm 1D4x10 M.D., each to everything in a 10 foot (3 m) radius; 200mm 1D6x10+10 M.D. to a 15 foot (4.6 m) radius.', 1, 'As per the tank gun firing it', NULL, NULL, NULL, NULL, NULL, 'The Sovietski main battle tank''s everyday shell: a charge of high explosive set off on impact. Anti-armor, then bombardment.', 'Rifts World Book 36: Sovietski p.190', NULL),
  ('sovietski-tank-round-heat', 'Tank Round: High Explosive Anti-Tank (HEAT)', 'rifts', 'weapon', NULL, 1200, 'Per round: 1,200 credits (85mm), 1,500 (100mm), 2,200 (120mm), 3,200 (200mm).', '85mm 1D4x10 M.D., 100mm 1D6x10 M.D., 120mm 2D4x10 M.D., each to everything in a 5 foot (1.5 m) radius; 200mm 2D6x10 M.D. to a 10 foot (3 m) radius.', 1, 'As per the tank gun firing it', NULL, NULL, NULL, NULL, NULL, 'A Sovietski tank shell built to kill other tanks and armored vehicles, hitting harder than plain high explosive over a tighter blast. Anti-armor, then bombardment.', 'Rifts World Book 36: Sovietski p.190', NULL),
  ('sovietski-tank-round-incendiary', 'Tank Round: Incendiary', 'rifts', 'weapon', NULL, 3000, '3,000 credits per shell, any caliber.', '1D6 M.D. on impact to whatever it strikes, then 2D6 M.D. per melee round for 1D6+1 melee rounds (or until put out) to everyone and everything splashed. Splash radius: 85mm 5 feet (1.3 m as printed), 100mm 10 feet (3 m), 120mm 15 feet (4.6 m), 200mm 20 feet (6.1 m). Creatures that fire harms more take double, fire-resistant ones half, fire-proof ones none.', 1, 'As per the tank gun firing it', NULL, NULL, NULL, NULL, NULL, 'A Sovietski tank shell full of a napalm-like liquid that sprays out on impact and catches fire in the air; a bigger caliber throws more of it over a wider area. The burning stuff does modest damage each melee round but is hard to put out without proper fire-retardant spray and usually has to burn itself out, and it readily sets fire to anything flammable nearby: a 01-20% chance of the flames spreading on a battlefield, 01-40% in a town or city. Area bombardment and anti-personnel, then anti-fortification.', 'Rifts World Book 36: Sovietski p.190', NULL),
  ('sovietski-tank-round-net', 'Tank Round: Net', 'rifts', 'weapon', NULL, 6000, '6,000 credits.', '1D6 M.D. from the barbs and hooks; flesh wings take 2D4 M.D., and a netted flyer stays down until it gets loose. The net has 30 M.D.C. -1 to strike.', 1, 'The tank gun''s range, less 20%', NULL, NULL, NULL, NULL, NULL, 'A Sovietski tank shell that bursts into a rapidly spreading net studded with barbs and hooks that catch on machinery, flesh, scales, horns and its own mesh. It is fired to hobble the legs and wings of big cyborgs, Brodkil and monsters, to bring down Gargoyles, Simvan monster riders and flying cyborgs or keep them from taking off, and to take heavy cyborgs and monsters alive for questioning or study. Most victims need 1D4 melee rounds to cut or tear free; on a Critical Strike the target is wrapped up completely and can take no physical action until a friend frees it, though it can still use psionics, spells and breath or eye attacks. Anti-monster and anti-cyborg, then capturing giants and animals.', 'Rifts World Book 36: Sovietski p.190-191', NULL),
  ('sovietski-tank-round-paint', 'Tank Round: Paint', 'rifts', 'weapon', NULL, 80, '80 credits each.', '4D6 S.D.C. -1 to strike.', 0, 'As per the tank gun firing it', NULL, NULL, NULL, NULL, NULL, 'An 85mm training and war-game shell holding 2 liters of marking paint, white for daytime or glowing for night exercises. Soldiers have noticed that the shell unscrews and can be refilled with nearly any liquid. Made only in 85mm.', 'Rifts World Book 36: Sovietski p.191', NULL),
  ('sovietski-tank-round-smoke', 'Tank Round: Smoke', 'rifts', 'weapon', NULL, 125, '125 credits per shell.', 'None. Smoke fills a 30 foot (9.1 m) radius and drifts downwind as a screen 20 feet (6.1 m) high.', 0, 'As per the tank gun firing it', NULL, NULL, NULL, NULL, NULL, 'A Sovietski tank shell that lays a smoke screen to hide troops moving, pulling out or retreating, or to blind and confuse the enemy''s fire. It keeps pouring smoke for one minute (4 melee rounds) and the cloud can hang for 1D6+4 minutes with the weather, half that in strong wind or heavy rain. It can also be used to break up civil unrest, or filled with tear gas or knockout gas instead.', 'Rifts World Book 36: Sovietski p.191', NULL),
  ('sovietski-tank-round-solid-slug', 'Tank Round: Solid Slug', 'rifts', 'weapon', NULL, 300, 'Per round: 300 credits (85mm), 400 (100mm), 500 (120mm), 700 (200mm).', '85mm 4D6 M.D.; 100mm 6D6 M.D.; 120mm 1D4x10 M.D.; 200mm 1D6x10 M.D. No blast radius.', 1, 'As per the tank gun firing it', NULL, NULL, NULL, NULL, NULL, 'The cheap, plain giant bullet of the Sovietski Tank Corps. Many tankers, Groundthunder crews above all, simply like hammering a target with solid metal; the ground shaking under a barrage of them is what the corps calls the Groundthunder Effect, and the 120mm slug is made in great numbers because of it. Anti-armor and anti-fortification, then anti-infantry and anti-monster.', 'Rifts World Book 36: Sovietski p.191', NULL),
  ('sovietski-tank-round-solid-slug-screaming', 'Tank Round: Solid Slug, Screaming or Whistling', 'rifts', 'weapon', NULL, 300, 'As the Solid Slug of the same caliber: 300 credits (85mm), 400 (100mm), 500 (120mm), 700 (200mm).', 'As the Solid Slug: 85mm 4D6 M.D.; 100mm 6D6 M.D.; 120mm 1D4x10 M.D.; 200mm 1D6x10 M.D. The enemy is -1 on Perception Rolls and -1 on initiative while the sound lasts, 1D4 melee rounds (15-60 seconds).', 1, 'The tank gun''s range, less 40% (the damage line says half)', NULL, NULL, NULL, NULL, NULL, 'A Sovietski solid slug cut with grooves that make it shriek or whistle in flight, so troops know they are under fire and lose their nerve. Mostly made in the smaller calibers. Psychological warfare.', 'Rifts World Book 36: Sovietski p.191', NULL),
  ('sovietski-tank-round-solid-slug-silver', 'Tank Round: Solid Slug, Silver', 'rifts', 'weapon', NULL, 2000, 'About 20,000 credits for a solid silver shell at European silver prices; 2,000 for a silver-coated shell; 3,000 for a silver flechette round.', 'Solid or silver-coated shell: 4D6 M.D. Flechette round: 3D6+20 silver-coated flechettes of 4D6 S.D.C. each over a 12 foot (3.7 m) swath. Double damage to creatures vulnerable to silver.', 1, 'As per the tank gun firing it', NULL, NULL, NULL, NULL, NULL, 'Silver-coated and solid silver tank shells, and an exploding silver flechette round, which the Sovietski fields against the werewolves spreading through the northern mountains and against demons that silver harms. Rumor says the silver comes from a world reached through a Rift, and that another Rift opens onto North America (Tolkeen, Canada or vampire-haunted Mexico, depending on who tells it) or onto France; the government dismisses the talk and never seems short of silver. Anti-monster.', 'Rifts World Book 36: Sovietski p.191', NULL),
  ('sovietski-tank-round-solid-slug-wood', 'Tank Round: Solid Slug, Wood', 'rifts', 'weapon', NULL, 800, '800 credits per round, or 6,000 for a crate of 12.', '2D6x10 S.D.C./Hit Points; counts as 1 M.D. against a tank, cyborg or other M.D.C. target. A 01-50% chance it shatters into 1D4x10 shards of 2D6 S.D.C. each across a 6 foot (1.8 m) wide spread; a shattered shell sprays 2D6 S.D.C. (1D6 M.D. to the wood-vulnerable) over everyone within 30 feet (9.1 m) ahead of the barrel. Vampires and anything else wood can hurt take double. -1 to strike.', 0, 'The tank gun''s range, less 20%', NULL, NULL, NULL, NULL, NULL, 'A big bullet of juniper or birch on a metal base, a tank-sized stake for Archaic Demons, vampires and other things wood can kill. Though the wood is kiln-dried and the base takes the force of firing, it often breaks up in flight. Next to useless against M.D.C. machines, but the splinters can be lethal to monsters, unarmored troops and bystanders. Anti-monster.', 'Rifts World Book 36: Sovietski p.192', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 11 gear rows are in' AS assertion, count(*) AS got, 11 AS want
  FROM gear WHERE slug IN ('sovietski-tank-round-armor-piercing', 'sovietski-tank-round-high-explosive', 'sovietski-tank-round-heat', 'sovietski-tank-round-incendiary', 'sovietski-tank-round-net', 'sovietski-tank-round-paint', 'sovietski-tank-round-smoke', 'sovietski-tank-round-solid-slug', 'sovietski-tank-round-solid-slug-screaming', 'sovietski-tank-round-solid-slug-silver', 'sovietski-tank-round-solid-slug-wood') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~389-sovietski-v4-rounds.sql');
